window.RTLBenchLSData.register("assets/d3a76faef792f68e9a17acfe9322b8ffdd0eb064a2bda14d854ea056cb763b22.txt","always @ (posedge clk or negedge rstn)\n    if(~rstn) begin\n        stat <= IDLE;\n        itoa_en <= 1'b0;\n        itoa_val <= 0;\n        vcnt <= 0;\n        cnt <= 0;\n        eov <= 8'h20;\n    end else begin\n        itoa_en <= 1'b0;\n        case(stat)\n            IDLE: if(i_en)\n                stat <= SELECT;\n            SELECT: begin\n                if         (vcnt==3'd0) begin\n                    vcnt <= vcnt + 3'd1;\n                    stat <= WAIT;\n                    itoa_en <= 1'b1;\n                    itoa_val <= i_val0;\n                    eov <= 8'h20;\n                end else if(vcnt==3'd1) begin\n                    vcnt <= vcnt + 3'd1;\n                    stat <= WAIT;\n                    itoa_en <= 1'b1;\n                    itoa_val <= i_val1;\n                    eov <= 8'h20;\n                end else if(vcnt==3'd2) begin\n                    vcnt <= vcnt + 3'd1;\n                    stat <= WAIT;\n                    itoa_en <= 1'b1;\n                    itoa_val <= i_val2;\n                    eov <= 8'h20;\n                end else if(vcnt==3'd3) begin\n                    vcnt <= vcnt + 3'd1;\n                    stat <= WAIT;\n                    itoa_en <= 1'b1;\n                    itoa_val <= i_val3;\n                    eov <= 8'h0A;\n                end else begin\n                    vcnt <= 3'd0;\n                    stat <= IDLE;\n                    eov <= 8'h20;\n                end\n            end\n            WAIT:\n                stat <= PARSING;\n            PARSING: if(itoa_oen)\n                stat <= SENDING;\n            default: //SENDING:\n                if(tx_rdy) begin\n                    cnt <= cnt + 3'd1;\n                    if(cnt==3'd7)\n                        stat <= SELECT;\n                end\n        endcase\n    end");
